.set-or-append Tabela_Alertas <|
// 1. Filtrar apenas os últimos 2 minutos
let Janela_Recente = V2 | where todatetime(Datahora_Evento) >= ago(2m);
//
// 2. Encontrar os "segundos de perigo" (Velocidade > 20 + Pressão > 3.5)
let Segundos_Perigo = Janela_Recente
    | where Tipo_de_Evento in ("Speed", "Brake Pressure")
    | summarize 
        Velocidade = maxif(todouble(Valor), Tipo_de_Evento == "Speed"),
        Pressao_Travoes = maxif(todouble(Valor), Tipo_de_Evento == "Brake Pressure")
        by Comboio, Carruagem, SegundoExato = bin(todatetime(Datahora_Evento), 1s)
    | where Velocidade > 20 and Pressao_Travoes > 3.5;
//
// 3. Recuperar os detalhes do sensor (Lat/Long/ID) usando a Pressão como âncora
Janela_Recente
| where Tipo_de_Evento == "Brake Pressure" and todouble(Valor) > 3.5
| extend SegundoExato = bin(todatetime(Datahora_Evento), 1s)
| join kind=inner (Segundos_Perigo) on Comboio, Carruagem, SegundoExato
//
// 4. Formatar para a Tabela_Alertas
| extend Tipo_Alerta = "PERIGO: Travões trancados em andamento (Brake Drag)"
| project 
    Carruagem = tostring(Carruagem), 
    Comboio = tostring(Comboio), 
    Datahora_Evento = todatetime(Datahora_Evento), 
    ID_Equipamento = tostring(ID_Equipamento), 
    Latitude = todouble(Latitude), 
    Longitude = todouble(Longitude), 
    TipoEquipamento = tostring(TipoEquipamento), 
    Tipo_de_Evento = tostring(Tipo_de_Evento), 
    Valor = todouble(Valor), 
    Tipo_Alerta
//
// 5. O Bloqueio Anti-Duplicados
| join kind=leftanti (
    Tabela_Alertas
    | where todatetime(Datahora_Evento) >= ago(3m)
    | where Tipo_Alerta == "PERIGO: Travões trancados em andamento (Brake Drag)"
) on Comboio, Carruagem, Datahora_Evento

.set-or-append Tabela_Alertas <|
// 1. Filtrar apenas os últimos 2 minutos para performance
let Janela_Recente = V2 | where todatetime(Datahora_Evento) >= ago(2m);
//
// 2. Encontrar os "segundos de perigo" (Porta aberta + Velocidade > 10)
let Segundos_Perigo = Janela_Recente
    | where Tipo_de_Evento in ("Door Open", "Speed")
    | summarize 
        Estado_Porta = maxif(toint(Valor), Tipo_de_Evento == "Door Open"),
        Velocidade = maxif(todouble(Valor), Tipo_de_Evento == "Speed")
        by Comboio, Carruagem, SegundoExato = bin(todatetime(Datahora_Evento), 1s)
    | where Estado_Porta == 1 and Velocidade > 10;
//
// 3. Recuperar os detalhes do sensor da porta (Lat/Long/ID) para guardar na tabela
Janela_Recente
| where Tipo_de_Evento == "Door Open" and toint(Valor) == 1
| extend SegundoExato = bin(todatetime(Datahora_Evento), 1s) // Criar a mesma chave de 1 segundo
| join kind=inner (Segundos_Perigo) on Comboio, Carruagem, SegundoExato // Só guarda se estiver na lista de perigo
//
// 4. Formatar para a Tabela_Alertas
| extend Tipo_Alerta = "PERIGO: Porta aberta com comboio em movimento"
| project 
    Carruagem = tostring(Carruagem), 
    Comboio = tostring(Comboio), 
    Datahora_Evento = todatetime(Datahora_Evento), 
    ID_Equipamento = tostring(ID_Equipamento), 
    Latitude = todouble(Latitude), 
    Longitude = todouble(Longitude), 
    TipoEquipamento = tostring(TipoEquipamento), 
    Tipo_de_Evento = tostring(Tipo_de_Evento), 
    Valor = todouble(Valor), 
    Tipo_Alerta
//
// 5. O Bloqueio Anti-Duplicados (proteção do Pipeline de 1 minuto)
| join kind=leftanti (
    Tabela_Alertas
    | where todatetime(Datahora_Evento) >= ago(3m) // Otimização: Só verifica duplicados recentes!
    | where Tipo_Alerta == "PERIGO: Porta aberta com comboio em movimento"
) on Comboio, Carruagem, Datahora_Evento

.set-or-append Tabela_Alertas <|
// 1. Filtrar apenas os últimos 2 minutos
let Janela_Recente = V2 | where todatetime(Datahora_Evento) >= ago(2m);
//
// 2. Encontrar os "segundos de perigo" (Motor ON + Temp > 95)
let Segundos_Perigo = Janela_Recente
    | where Tipo_de_Evento in ("Engine State", "Engine Temperature")
    | summarize 
        Estado_Motor = maxif(todouble(Valor), Tipo_de_Evento == "Engine State"),
        Temp_Motor = maxif(todouble(Valor), Tipo_de_Evento == "Engine Temperature")
        by Comboio, Carruagem, SegundoExato = bin(todatetime(Datahora_Evento), 1s)
    | where Estado_Motor == 1 and Temp_Motor > 95;
//
// 3. Recuperar os detalhes do sensor usando a Temperatura como âncora
Janela_Recente
| where Tipo_de_Evento == "Engine Temperature" and todouble(Valor) > 95
| extend SegundoExato = bin(todatetime(Datahora_Evento), 1s)
| join kind=inner (Segundos_Perigo) on Comboio, Carruagem, SegundoExato
//
// 4. Formatar para a Tabela_Alertas (Em Inglês para a tese)
| extend Tipo_Alerta = "CRITICAL: Engine Overheat (>95ºC)"
| project 
    Carruagem = tostring(Carruagem), 
    Comboio = tostring(Comboio), 
    Datahora_Evento = todatetime(Datahora_Evento), 
    ID_Equipamento = tostring(ID_Equipamento), 
    Latitude = todouble(Latitude), 
    Longitude = todouble(Longitude), 
    TipoEquipamento = tostring(TipoEquipamento), 
    Tipo_de_Evento = tostring(Tipo_de_Evento), 
    Valor = todouble(Valor), 
    Tipo_Alerta
//
// 5. O Bloqueio Anti-Duplicados
| join kind=leftanti (
    Tabela_Alertas
    | where todatetime(Datahora_Evento) >= ago(3m)
    | where Tipo_Alerta == "CRITICAL: Engine Overheat (>95ºC)"
) on Comboio, Carruagem, Datahora_Evento
